}

struct ListNode* buildListNK(int* k) {
    int n = 0;
    if (scanf("%d %d", &n, k) != 2) return NULL;
    int ch;
    while ((ch = getchar()) != '\n' && ch != EOF) {}
    char line[65536];
    if (!fgets(line, sizeof(line), stdin)) return NULL;
    struct ListNode *head = NULL, *tail = NULL;
    char *tok = strtok(line, " \t\r\n");
    while (tok) {
        struct ListNode* node = newListNode(atoi(tok));
        if (!head) head = tail = node; else { tail->next = node; tail = node; }
        tok = strtok(NULL, " \t\r\n");
    }
    return head;
}

