            TreeNode cur = q.poll();
            if (i < toks.length && !isNullTok(toks[i])) {
                cur.left = new TreeNode(Integer.parseInt(toks[i]));
                q.offer(cur.left);
            }
            i++;
            if (i < toks.length && !isNullTok(toks[i])) {
                cur.right = new TreeNode(Integer.parseInt(toks[i]));
                q.offer(cur.right);
            }
            i++;
        }
