static struct TreeNode* buildTreeFromInput(void) {
    char line[65536];
    if (!fgets(line, sizeof(line), stdin)) return NULL;
    char* toks[4096]; int tc = 0;
    char* tok = strtok(line, " \t\r\n");
    while (tok && tc < 4096) { toks[tc++] = tok; tok = strtok(NULL, " \t\r\n"); }
    if (tc == 0 || isNullTok(toks[0])) return NULL;
    struct TreeNode* root = newTreeNode(atoi(toks[0]));
    struct TreeNode** q = (struct TreeNode**)malloc(sizeof(struct TreeNode*) * 4096);
    int h = 0, t = 0; q[t++] = root; int i = 1;
    while (h < t && i < tc) {
        struct TreeNode* cur = q[h++];
        if (i < tc && !isNullTok(toks[i])) { cur->left = newTreeNode(atoi(toks[i])); q[t++] = cur->left; }
        i++;
        if (i < tc && !isNullTok(toks[i])) { cur->right = newTreeNode(atoi(toks[i])); q[t++] = cur->right; }
        i++;
    }
    free(q);
    return root;
}
"}

